qboolean MR_WrathIOSApplyMenuPointer(void)
{
	prvm_prog_t *prog = MVM_prog;
	ddef_t *ui_mouseposition;
	prvm_vec_t *cursor;
	float logical_x, logical_y;
	float virtual_x, virtual_y;
	if (!prog->loaded || !WrathIOSInputGetMenuPosition(&logical_x, &logical_y))
		return false;
	ui_mouseposition = PRVM_ED_FindGlobal(prog, "ui_mouseposition");
	if (!ui_mouseposition || vid.width <= 0 || vid.height <= 0)
		return false;
	virtual_x = logical_x * vid_conwidth.integer / vid.width;
	virtual_y = logical_y * vid_conheight.integer / vid.height;
	cursor = PRVM_GLOBALFIELDVECTOR(ui_mouseposition->ofs);
	cursor[0] = bound(0, virtual_x, vid_conwidth.integer);
	cursor[1] = bound(0, virtual_y, vid_conheight.integer);
	cursor[2] = 0;
	WrathIOSInputMarkMenuPositionApplied();
	WrathIOSInputTraceMenuQCPointerApplied(logical_x, logical_y, cursor[0], cursor[1]);
	return true;
}

